import{_ as t,o as i,c as o,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2022-11-30","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2022-11-30","date":"2022-11-30T00:00:00.000Z","updated":"2022-11-30T00:00:00.000Z","tags":["Ceph","RGW","配置变量","RADOS","测试和重构"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_RGW_Refactoring_Meeting_2022-11-30.md","filePath":"posts/2022/Ceph_RGW_Refactoring_Meeting_2022-11-30.md","lastUpdated":1780459816000}'),a={name:"posts/2022/Ceph_RGW_Refactoring_Meeting_2022-11-30.md"};function p(r,e,s,n,_,R){return i(),o("div",null,[...e[0]||(e[0]=[l("<p>会议主要讨论了以下几个议题：</p><ol><li><p><strong>文档配置变量标签化</strong>：Ali正在为文档中的所有配置变量添加标签，以确定它们是否可以在运行时设置或更改。已创建了一个PR并渲染了文档，下一步计划是通过审计所有配置变量来进一步完善。建议使用Pad而不是Google Sheet来共享和更新这些变量的信息。</p></li><li><p><strong>RADOS中的竞价持久化问题</strong>：讨论了在RADOS中持久化竞价信息的问题，特别是如何在不违反现有规则的情况下处理这些信息。提出了使用CLS锁和XAttr来存储竞价信息，但遇到了持久化和错误返回的复杂性。计划与RADOS团队进一步讨论，寻找解决方案。</p></li><li><p><strong>RGW开发入门文档</strong>：讨论了为新开发者提供的入门文档，建议参考upstream.com上的资源。强调了RGW作为S3层的重要性，并欢迎新贡献者加入。</p></li><li><p><strong>测试和代码重构</strong>：讨论了多个PR的测试和重构问题，包括Caleb和Matt的PR。计划合并相关PR，以减少未来的重构工作量。</p></li><li><p><strong>Neorados的合并问题</strong>：讨论了Neorados的合并问题，计划重新运行测试并联系RBD团队以获取反馈。</p></li></ol><p>会议决定事项：</p><ul><li>使用Pad来管理配置变量的审计和更新。</li><li>继续与RADOS团队讨论竞价信息的持久化问题。</li><li>合并Caleb和Matt的PR，以减少未来的重构工作量。</li><li>重新运行Neorados的测试，并联系RBD团队以获取反馈。</li></ul><p>后续行动计划：</p><ul><li>Ali将继续完善配置变量的审计工作，并使用Pad进行信息共享。</li><li>与RADOS团队进一步讨论竞价信息的持久化问题，并寻找解决方案。</li><li>Caleb和Matt将合并他们的PR，并进行必要的重构和测试。</li><li>重新运行Neorados的测试，并联系RBD团队以获取反馈。</li></ul><p>会议还鼓励新开发者加入Ceph项目，并提供入门文档和开发环境的设置建议。</p>",7)])])}const c=t(a,[["render",p]]);export{d as __pageData,c as default};
